    /** @description Total number of invoices successfully updated to 'Overdue' */
    private Integer recordsUpdated = 0;

    /** @description Total number of invoices that failed to update (e.g., due to validation rules) */
    private Integer recordsFailed = 0;

    /** @description Cumulative sum of the Amount__c of successfully updated invoices */
    private Decimal overdueAmount = 0.0;

