/**
 * Provides functionality to batch-process account rating updates via Queueable chaining.
 */
public with sharing class AccountScoringJob implements Queueable {
    private List<Id> accountIds;

    /**
     * @param accountIds List of Account IDs to be processed in this and subsequent jobs.
     */
    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    /**
     * Starts the account scoring job chain.
     * @param accountIds List of Account IDs to process.
     * @return The ID of the first queued job, or null if the list is empty.
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    /**
     * Executes the scoring logic for a batch of up to 200 accounts.
     * @param context The queueable context.
     */
    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Determine the batch for this execution (max 200)
        int limitSize = Math.min(accountIds.size(), 200);
        List<Id> currentBatchIds = accountIds.subList(0, limitSize);

        // Prepare the remaining list for the next job in the chain
        List<Id> remainingIds = new List<Id>();
        if (accountIds.size() > limitSize) {
            remainingIds = accountIds.subList(limitSize, accountIds.size());
        }

        // Perform the work: One SOQL and One DML
        if (!currentBatchIds.isEmpty()) {
            List<Account> accountsToUpdate = [
                SELECT Id, AnnualRevenue, Rating
                FROM Account
                WHERE Id IN :currentBatchIds
                WITH USER_MODE
            ];

            for (Account acc : accountsToUpdate) {
                Decimal revenue = acc.AnnualRevenue;
                if (revenue != null && revenue >= 1000000) {
                    acc.Rating = 'Hot';
                } else if (revenue != null && revenue >= 100000) {
                    acc.Rating = 'Warm';
                } else {
                    acc.Rating = 'Cold';
                }
            }

            if (!accountsToUpdate.isEmpty()) {
                update as user accountsToUpdate;
            }
        }

        // Chain the next job if needed
        if (!remainingIds.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remainingIds));
        }
    }
}
