export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    @api 
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = val || [];
        this._updateActiveIndex();
    }

    _value;
    @api 
    get value() {
        return this._value;
    }
    set value(val) {
        if (this._value !== val) {
            this._value = val;
            this._updateActiveIndex();
        }
    }

    activeOptionIndex = 0;

    _updateActiveIndex() {
        if (this._options && this._options.length > 0) {
            const index = this._options.findIndex(opt => opt.value === this._value);
            if (index !== -1) {
                this.activeOptionIndex = index;
            } else {
                this.activeOptionIndex = 0;
            }
        } else {
            this.activeOptionIndex = 0;
        }
    }

    get activeOptionId() {
        if (this._options && this._options[this.activeOptionIndex]) {
            return `option-${this._options[this.activeOptionIndex].value}`;
        }
        return '';
    }

    get processedOptions() {
        return this._options.map(opt => ({
            ...opt,
            id: `option-${opt.value}`,
            isSelected: opt.value === this._value
        }));
    }

    handleKeyDown(event) {
        if (this._options.length === 0) return;

        const { key } = event;
        let newIndex = this.activeOptionIndex;

        if (key === 'ArrowDown') {
            newIndex = Math.min(this.activeOptionIndex + 1, this._options.length - 1);
        } else if (key === 'ArrowUp') {
            newIndex = Math.max(this.activeOptionIndex - 1, 0);
        } else if (key === 'Home') {
            newIndex = 0;
        } else if (key === 'End') {
            newIndex = this._options.length - 1;
        } else if (key === 'Enter' || key === ' ') {
            event.preventDefault();
            const selectedValue = this._options[this.activeOptionIndex].value;
            this.handleSelect(selectedValue);
            return;
        } else {
            return;
        }

        event.preventDefault();
        this.activeOptionIndex = newIndex;
    }

    handleOptionClick(event) {
        const value = event.currentTarget.dataset.value;
        const index = this._options.findIndex(opt => opt.value === value);
        if (index !== -1) {
            this.activeOptionIndex = index;
            this.handleSelect(value);
        }
    }

    handleSelect(value) {
        if (value !== this._value) {
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value }
            }));
        }
    }
