import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    @api
    get options() {
        return this._options;
    }
    set options(value) {
        this._options = value || [];
        this._syncActiveIndex();
    }

    _value;
    @api
    get value() {
        return this._value;
    }
    set value(value) {
        this._value = value;
        this._syncActiveIndex();
    }

    activeOptionIndex = 0;

    _syncActiveIndex() {
        if (this._options && this._options.length > 0) {
            const index = this._options.findIndex(opt => opt.value === this._value);
            if (index !== -1) {
                this.activeOptionIndex = index;
            } else {
                this.activeOptionIndex = 0;
            }
        } else {
            this.activeOptionIndex = 0;
        }
    }

    get activeOptionId() {
        if (this._options && this._options.length > 0) {
            return `option-${this.activeOptionIndex}`;
        }
        return '';
    }

    get mappedOptions() {
        return (this._options || []).map((option, index) => ({
            ...option,
            id: `option-${index}`,
            isSelected: option.value === this._value
        }));
    }

    handleKeyDown(event) {
        const { key } = event;
        let handled = true;

        if (key === 'ArrowDown') {
            if (this.activeOptionIndex < this._options.length - 1) {
                this.activeOptionIndex++;
            }
        } else if (key === 'ArrowUp') {
            if (this.activeOptionIndex > 0) {
                this.activeOptionIndex--;
            }
        } else if (key === 'Home') {
            this.activeOptionIndex = 0;
        } else if (key === 'End') {
            this.activeOptionIndex = this._options.length - 1;
        } else if (key === 'Enter' || key === ' ') {
            this.selectOption(this._options[this.activeOptionIndex]);
        } else {
            handled = false;
        }

        if (handled) {
            event.preventDefault();
        }
    }

    handleOptionClick(event) {
        const valueStr = event.currentTarget.dataset.value;
        const option = this._options.find(opt => String(opt.value) === valueStr);
        if (option) {
            this.activeOptionIndex = this._options.indexOf(option);
            this.selectOption(option);
        }
    }

    selectOption(option) {
        if (option && option.value !== this._value) {
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value: option.value }
            }));
        }
    }
